const state={data:null,selected:null,filter:'all'};
const $=s=>document.querySelector(s);
const fmt=n=>n==null?'—':new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(n);
function renderStats(a){const q=[['qualified_runs','Qualified GPS runs',a.qualified_runs],['published_corridors','Screened corridors',a.published_corridors],['positions','Raw positions',a.positions],['vehicle_activities','Vehicle segments',a.vehicle_activities],['tms_miami_rows','Miami TMS records',a.gis_context?.tms_miami_rows],['count_station_aadt_rows','2019 AADT stations',a.gis_context?.count_station_aadt_rows]];$('#stats').innerHTML=q.map(x=>`<div class="stat"><div class="value">${fmt(x[2])}</div><div class="label">${x[1]}</div></div>`).join('');$('#period').textContent=`${a.analysis_period.start.slice(0,10)} — ${a.analysis_period.end.slice(0,10)} · local processing`}
function filtered(){return state.data.corridors.filter(c=>state.filter==='all'||c.status===state.filter)}
function renderList(){let rows=filtered();$('#corridor-list').innerHTML=rows.map((c,i)=>`<button class="corridor-row ${state.selected===c.id?'active':''}" data-id="${c.id}"><span class="rank">${String(i+1).padStart(2,'0')}</span><span><span class="row-title">${c.location_label||c.label}</span><span class="tag ${c.status}">${c.status}</span><span class="row-meta">${c.sample_count} traversals · ${c.day_count} days</span></span><span class="delta">${c.comparison?`+${fmt(c.comparison.difference_seconds)}s`:'—'}</span></button>`).join('');document.querySelectorAll('.corridor-row').forEach(b=>b.onclick=()=>{state.selected=b.dataset.id;renderList();renderDetail()});if(!state.selected&&rows[0]){state.selected=rows[0].id;renderList();renderDetail()}}
function drawMap(){
  const map=$('#map');
  const old=map.querySelector('svg'); if(old) old.remove();
  const cs=state.data.corridors||[]; const pts=cs.flatMap(c=>c.geometry.coordinates);
  if(!pts.length)return;
  const xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]);
  const pad=.012, minx=Math.min(...xs)-pad,maxx=Math.max(...xs)+pad,miny=Math.min(...ys)-pad,maxy=Math.max(...ys)+pad;
  const sx=x=>(x-minx)/(maxx-minx||1)*100, sy=y=>100-(y-miny)/(maxy-miny||1)*100;
  const svg=document.createElementNS('http://www.w3.org/2000/svg','svg'); svg.setAttribute('viewBox','0 0 100 100'); svg.setAttribute('role','img'); svg.setAttribute('aria-label','Evidence corridor map');
  const defs=`<defs><filter id="shadow" x="-20%" y="-20%" width="140%" height="140%"><feDropShadow dx="0" dy=".35" stdDeviation=".45" flood-color="#13262d" flood-opacity=".22"/></filter><linearGradient id="water" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#dcefed"/><stop offset="1" stop-color="#eef7f5"/></linearGradient></defs>`;
  const water=`<path d="M0 0H16C11 18 13 35 8 51C4 66 9 83 4 100H0Z" fill="url(#water)"/><path d="M100 0H91C94 19 89 37 94 54C98 71 91 85 96 100H100Z" fill="#e9f3f1"/>`;
  const roads=[]; for(let i=0;i<11;i++){const y=8+i*8.7;roads.push(`<path d="M0 ${y} C28 ${y-3}, 62 ${y+3}, 100 ${y-1}"/>`)} for(let i=0;i<9;i++){const x=12+i*10.5;roads.push(`<path d="M${x} 0 C${x-3} 26, ${x+3} 72, ${x-1} 100"/>`)}
  let body=`${defs}${water}<g class="base-roads">${roads.join('')}</g>`;
  cs.forEach(c=>{const [a,b]=c.geometry.coordinates;const active=state.selected===c.id;const w=Math.max(0.8,Math.min(2.7,0.7+c.sample_count/5));const color=c.status==='supported'?'#236b78':'#8aa8a4';body+=`<line x1="${sx(a[0])}" y1="${sy(a[1])}" x2="${sx(b[0])}" y2="${sy(b[1])}" stroke="${color}" stroke-width="${active?w+.9:w}" stroke-linecap="round" opacity="${active?1:.78}" ${active?'filter="url(#shadow)"':''}/><circle cx="${sx(a[0])}" cy="${sy(a[1])}" r="${active?1.65:1.05}" fill="${c.status==='supported'?'#7ce0c3':'#d4e4e0'}" stroke="#fff" stroke-width=".35"/>`;
    if(active){const lx=(sx(a[0])+sx(b[0]))/2,ly=(sy(a[1])+sy(b[1]))/2;body+=`<g class="map-label-svg"><rect x="${lx-14}" y="${ly-4.2}" width="28" height="7" rx="2"/><text x="${lx}" y="${ly+.5}" text-anchor="middle">${c.id} · ${c.status}</text></g>`}
    (c.nearby_signals||[]).slice(0,2).forEach((q,j)=>{const t=(j+1)/3;const x=sx(a[0]+(b[0]-a[0])*t),y=sy(a[1]+(b[1]-a[1])*t);body+=`<circle class="signal-dot" cx="${x}" cy="${y}" r=".8"/>`});
  });
  body+=`<g class="map-chrome"><text x="4" y="7" class="map-title-svg">MIAMI-DADE</text><text x="4" y="11" class="map-subtitle-svg">sampled corridor evidence</text><path d="M92 17v-7m0-3-1.8 3H94z"/><text x="92" y="21" text-anchor="middle" class="north-svg">N</text><path d="M5 92h12"/><text x="5" y="96" class="scale-svg">approx. 1 mile</text></g>`;
  svg.innerHTML=body; map.appendChild(svg);
}
function renderDetail(){const c=state.data.corridors.find(x=>x.id===state.selected);if(!c)return;drawMap();const d=c.comparison?.difference_seconds||0;const pct=Math.max(10,Math.min(100,c.median_seconds/6));const tmss=c.tms_context?.matched_sites||[];const tms=tmss.map(s=>`${s.name} ${s.direction} · peak window ${fmt(s.peak_window_volume)} vehicles · ${s.days} days`).join('; ');const countss=c.count_station_context?.matched_stations||[];const counts=countss.map(s=>`${s.address} · AADT 2019 ${fmt(s.aadt2019)} · ${fmt(s.distance_m)}m away`).join('; ');const volumeDefault=c.comparison&&tmss[0]?.peak_window_volume?tmss[0].peak_window_volume:'';$('#detail').innerHTML=`<div class="detail-grid"><div class="detail-main"><div class="kicker">${c.id} · ${c.status.toUpperCase()}</div><h2>${c.location_label||c.label}</h2><p class="small">${c.note}</p><div class="metric-row"><div class="metric"><b>${fmt(c.median_seconds)}s</b><small>median traversal</small></div><div class="metric"><b>${c.comparison?`+${fmt(d)}s`:'—'}</b><small>peak vs midday</small></div><div class="metric"><b>${c.sample_count}</b><small>accepted traversals</small></div></div><div class="bars"><div class="bar-wrap"><div class="bar" style="height:${pct}%"></div><span class="bar-label">overall</span></div><div class="bar-wrap"><div class="bar mid" style="height:${Math.max(8,pct-d/4)}%"></div><span class="bar-label">midday reference</span></div></div><p class="small">Observed comparison only. It is not proven removable delay. Traffic counts shown here are context; they do not validate the sampled GPS as representative of all traffic.</p></div><div class="detail-side"><div class="kicker">EVIDENCE</div><h2>What this supports</h2><p class="small">${c.status==='supported'?'A repeated peak–midday difference is visible in the sampled history.':'The route has repeat observations, but not enough comparable windows for a supported peak comparison.'}</p><p class="small"><strong>Signal context:</strong> ${(c.nearby_signals||[]).map(s=>`${s.intersection} (${s.distance_m}m)`).join('; ')||'No supplied signal within 700m'}</p><p class="small"><strong>TMS context:</strong> ${tms||'No matched FDOT count site for this road name. This corridor remains unweighted.'}</p><p class="small"><strong>Count-station context:</strong> ${counts||'No nearby 2019 AADT station matched by road name.'} <span class="small">AADT is annual average traffic, not directional peak volume.</span></p><p class="small"><strong>Coverage months:</strong> ${(c.months||[]).join(', ')}</p><p class="small"><strong>Next verification:</strong> match the segment itself to the supplied StreetNetwork geometry, then review with a county engineer.</p><div class="scenario"><div class="kicker">CONDITIONAL ANNUAL VALUE</div><h2>Test a reduction assumption</h2><div class="scenario-grid"><div><label>Reduction</label><input id="fraction" type="number" min="0" max="100" value="20" /></div><div><label>Peak-window vehicles</label><input id="volume" type="number" min="0" value="${volumeDefault}" placeholder="required" /></div><div><label>Value of time ($/person-hr)</label><input id="vot" type="number" min="0" value="19.60" /></div></div><div class="scenario-result" id="scenario-result">Requires a supported GPS comparison and matched TMS volume.</div></div></div></div>`;['fraction','volume','vot'].forEach(id=>$('#'+id).addEventListener('input',updateScenario));updateScenario()}
function updateScenario(){const c=state.data.corridors.find(x=>x.id===state.selected), f=Number($('#fraction')?.value||0)/100,q=Number($('#volume')?.value||0),v=Number($('#vot')?.value||0),d=c?.comparison?.difference_seconds||0;if(!q||!v||!d||!c?.tms_context?.matched_sites?.length){$('#scenario-result').innerHTML='Requires a supported GPS comparison and matched TMS volume.';return}const annual=d*f/3600*q*250*v*1.48;$('#scenario-result').innerHTML=`Estimated annual person-time value: <strong>$${Math.round(annual).toLocaleString()}</strong><br><span class="small">Conditional: ${fmt(d*f)} seconds saved per vehicle, ${q.toLocaleString()} vehicles in the matched peak window, 1.48 occupants/vehicle, 250 weekdays, $${v.toFixed(2)}/person-hour.</span>`}
function download(){const c=state.data.corridors.find(x=>x.id===state.selected);const row={id:c.id,label:c.label,status:c.status,sample_count:c.sample_count,day_count:c.day_count,median_seconds:c.median_seconds,peak_midday_difference_seconds:c.comparison?.difference_seconds||'',note:c.note};const blob=new Blob([Object.keys(row).join(',')+'\n'+Object.values(row).map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${c.id}-summary.csv`;a.click();URL.revokeObjectURL(a.href)}
async function init(){try{const r=await fetch('analysis.json');state.data=await r.json();renderStats(state.data.quality_summary);drawMap();renderList();$('#filter').onchange=e=>{state.filter=e.target.value;state.selected=null;renderList();renderDetail()};$('#download').onclick=download}catch(e){$('#detail').innerHTML='<div class="empty"><h2>Dataset could not be loaded</h2><p>Run the local analysis pipeline to rebuild the sanitized data bundle.</p></div>'}}
init();
